CREATE UNIQUE INDEX "hitl_flow_question_turn_uq" ON "hitl_requests" USING btree ("flow_node_attempt_id",("schema"->'flowQuestion'->>'promptOrdinal')) WHERE "hitl_requests"."flow_node_attempt_id" IS NOT NULL;--> statement-breakpoint
ALTER TABLE "hitl_requests" ADD CONSTRAINT "hitl_flow_question_shape_check" CHECK ((
      ("hitl_requests"."flow_node_attempt_id" IS NULL AND "hitl_requests"."flow_request_key" IS NULL AND "hitl_requests"."flow_answer_accepted_at" IS NULL AND "hitl_requests"."flow_answer_user_id" IS NULL AND "hitl_requests"."flow_reconciled_at" IS NULL)
      OR ("hitl_requests"."flow_node_attempt_id" IS NOT NULL AND "hitl_requests"."kind"='agent_question' AND length("hitl_requests"."flow_request_key") BETWEEN 1 AND 128
        AND jsonb_typeof("hitl_requests"."schema"->'flowQuestion'->'promptOrdinal')='number'
        AND "hitl_requests"."schema"->'flowQuestion'->>'nodeAttemptId'="hitl_requests"."flow_node_attempt_id"
        AND jsonb_typeof("hitl_requests"."schema"->'flowQuestion'->'commandId')='string'
        AND jsonb_typeof("hitl_requests"."schema"->'flowQuestion'->'assignmentId')='string'
        AND jsonb_typeof("hitl_requests"."schema"->'flowQuestion'->'incarnationId')='string'
        AND jsonb_typeof("hitl_requests"."schema"->'supervisorSessionId')='string' AND jsonb_typeof("hitl_requests"."schema"->'tokenId')='string'
        AND "hitl_requests"."schema"->>'requestDigest' ~ '^[a-f0-9]{64}$'
        AND "hitl_requests"."task_id" IS NULL AND "hitl_requests"."specialist_assignment_id" IS NULL AND "hitl_requests"."retrigger_mode" IS NULL
        AND (("hitl_requests"."flow_answer_accepted_at" IS NULL AND "hitl_requests"."flow_answer_user_id" IS NULL AND "hitl_requests"."response" IS NULL AND "hitl_requests"."responded_at" IS NULL)
          OR ("hitl_requests"."flow_answer_accepted_at" IS NOT NULL AND "hitl_requests"."flow_answer_user_id" IS NOT NULL AND "hitl_requests"."response" IS NOT NULL AND "hitl_requests"."activation_state"='active')))
      ) IS TRUE);--> statement-breakpoint
ALTER TABLE "hitl_requests" ADD CONSTRAINT "hitl_requests_agent_question_shape_check" CHECK ((
        "hitl_requests"."kind" = 'agent_question'
        AND (("hitl_requests"."flow_node_attempt_id" IS NULL AND ("hitl_requests"."task_id" IS NULL) <> ("hitl_requests"."specialist_assignment_id" IS NULL) AND "hitl_requests"."retrigger_mode" IS NOT NULL) OR "hitl_requests"."flow_node_attempt_id" IS NOT NULL)
        AND "hitl_requests"."activation_state" IS NOT NULL
        AND "hitl_requests"."schema" IS NOT NULL
      ) OR (
        "hitl_requests"."kind" <> 'agent_question'
        AND "hitl_requests"."task_id" IS NULL
        AND "hitl_requests"."activation_state" IS NULL
        AND "hitl_requests"."retrigger_mode" IS NULL
      ));--> statement-breakpoint
ALTER TABLE "node_attempts" ADD CONSTRAINT "node_attempts_action_resume_check" CHECK ("node_attempts"."action_resume" IS NULL OR (jsonb_typeof("node_attempts"."action_resume") = 'object' AND "node_attempts"."action_resume"->'version' = '1'::jsonb AND (("node_attempts"."action_resume"->>'kind' = 'clarification' AND jsonb_typeof("node_attempts"."action_resume"->'questionId')='string' AND jsonb_typeof("node_attempts"."action_resume"->'sourceIncarnationId')='string' AND ("node_attempts"."action_resume"->'answer'='null'::jsonb OR (jsonb_typeof("node_attempts"."action_resume"->'answer')='object' AND jsonb_typeof("node_attempts"."action_resume"->'answer'->'inputRevision')='number' AND "node_attempts"."action_resume"->'answer'->>'inputSha256' ~ '^[a-f0-9]{64}$' AND "node_attempts"."action_resume"->'answer'->>'receiptSha256' ~ '^[a-f0-9]{64}$' AND jsonb_typeof("node_attempts"."action_resume"->'answer'->'checkpointCommandId')='string'))) OR ("node_attempts"."action_resume"->>'kind' = 'node_question' AND jsonb_typeof("node_attempts"."action_resume"->'questionId')='string' AND jsonb_typeof("node_attempts"."action_resume"->'checkpointCommandId')='string' AND jsonb_typeof("node_attempts"."action_resume"->'sourceIncarnationId')='string') OR ("node_attempts"."action_resume"->>'kind' = 'interrupt' AND "node_attempts"."action_resume"->>'cause' IN ('operator', 'host_pressure')) OR ("node_attempts"."action_resume"->>'kind' = 'orchestrator' AND (NOT ("node_attempts"."action_resume" ? 'permissionResult') OR (jsonb_typeof("node_attempts"."action_resume"->'permissionResult') = 'object' AND "node_attempts"."action_resume"->'permissionResult'->'version' = '1'::jsonb AND "node_attempts"."action_resume"->'permissionResult'->>'kind' = 'permission_result' AND "node_attempts"."action_prompt_ordinal" > 0 AND "node_attempts"."action_resume"->'permissionResult'->'promptOrdinal' = to_jsonb("node_attempts"."action_prompt_ordinal" - 1) AND "node_attempts"."action_resume"->'permissionResult'->>'sourceCommandId' = "node_attempts"."action_resume"->>'sourceCommandId' AND "node_attempts"."action_resume"->'permissionResult'->>'sourceAssignmentId' = "node_attempts"."action_resume"->>'sourceAssignmentId' AND "node_attempts"."action_resume"->'permissionResult'->>'resumeSessionId' = "node_attempts"."action_resume"->>'resumeSessionId' AND jsonb_typeof("node_attempts"."action_resume"->'permissionResult'->'assignmentId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'permissionResult'->'hitlRequestId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'permissionResult'->'sourceRequestId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'permissionResult'->'optionId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'permissionResult'->'inputCommandId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'permissionResult'->'checkpointCommandId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'permissionResult'->'sourceIncarnationId') = 'string'))) OR (("node_attempts"."action_resume"->>'kind' = 'permission' OR ("node_attempts"."action_resume"->>'kind' = 'permission_continue' AND "node_attempts"."action_prompt_ordinal" > 0 AND jsonb_typeof("node_attempts"."action_resume"->'checkpointCommandId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'inputCommandId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'sourceIncarnationId') = 'string') OR ("node_attempts"."action_resume"->>'kind' = 'permission_result' AND "node_attempts"."action_completion"->>'commandId' = "node_attempts"."action_resume"->>'sourceCommandId' AND jsonb_typeof("node_attempts"."action_resume"->'checkpointCommandId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'inputCommandId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'sourceIncarnationId') = 'string')) AND jsonb_typeof("node_attempts"."action_resume"->'hitlRequestId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'sourceRequestId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'optionId') = 'string')) AND jsonb_typeof("node_attempts"."action_resume"->'sourceCommandId') = 'string' AND jsonb_typeof("node_attempts"."action_resume"->'sourceAssignmentId') = 'string' AND "node_attempts"."action_resume"->>'assignmentId' = "node_attempts"."execution_assignment_id" AND "node_attempts"."action_resume"->'promptOrdinal' = to_jsonb("node_attempts"."action_prompt_ordinal") AND jsonb_typeof("node_attempts"."action_resume"->'resumeSessionId') = 'string') IS TRUE);